// ARR - Cost and iteration ceiling: the workflows to watch. Ceilings are in Check.
const WATCH = ['<workflow id>'];
return WATCH.filter(id => id && !id.startsWith('<')).map(id => ({ json: { id } }));

// ARR - Cost and iteration ceiling. Ceilings come from the report (section 5), usually 5x the
// 30-day median for each workflow. A run over any ceiling is reported once.
const CONFIG = {
  window_minutes: 15,            // match the schedule
  default: { max_duration_s: 300, max_iterations: 25, max_tokens: 200000 },
  per_workflow: {},              // { 'aBc123': { max_duration_s: 120, max_iterations: 10, max_tokens: 50000 } }, by workflow id
};

const now = Date.now();
const since = now - CONFIG.window_minutes * 60000;
function tokens(obj) {
  let total = 0;
  const walk = v => {
    if (!v || typeof v !== 'object') return;
    if (Array.isArray(v)) { v.forEach(walk); return; }
    for (const [k, x] of Object.entries(v)) {
      if ((k === 'tokenUsage' || k === 'tokenUsageEstimate') && x && typeof x === 'object') {
        total += Number(x.totalTokens || ((x.promptTokens || 0) + (x.completionTokens || 0))) || 0;
      } else walk(x);
    }
  };
  walk(obj);
  return total;
}
const problems = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e || e.id === undefined) continue;
  const started = new Date(e.startedAt).getTime();
  const ended = e.stoppedAt ? new Date(e.stoppedAt).getTime() : now;
  const lim = { ...CONFIG.default, ...(CONFIG.per_workflow[e.workflowId] || {}) };
  const running = !e.stoppedAt;
  if (!running && ended < since) continue;
  const duration = (ended - started) / 1000;
  const runData = (e.data && e.data.resultData && e.data.resultData.runData) || {};
  const iterations = Math.max(0, ...Object.values(runData).map(r => (Array.isArray(r) ? r.length : 0)));
  const used = tokens(runData);
  const over = [];
  if (duration > lim.max_duration_s) over.push(`${Math.round(duration)} s${running ? ' and still running' : ''} (ceiling ${lim.max_duration_s} s)`);
  if (iterations > lim.max_iterations) over.push(`${iterations} node runs (ceiling ${lim.max_iterations})`);
  if (used > lim.max_tokens) over.push(`${used} tokens (ceiling ${lim.max_tokens})`);
  if (over.length) problems.push(`execution ${e.id} of workflow ${e.workflowId} is over, ${over.join(', ')}`);
}
if (problems.length) {
  throw new Error(`ARR - Cost and iteration ceiling failed, ${problems.length} run(s) over a ceiling. ${problems.join('; ')}`);
}
return [{ json: { ok: true, checked: $input.all().length } }];
